-- Deletion vectors, inline files and footers (§10, §11).

-- Blobs written by an independent implementation (pyroaring 1.1.0 and zlib): an array container, a run container
-- written with the run cookie, positions above 2^32, run containers, the empty vector, and a bitset container.
create table vectors (name text, blob bytea, positions bigint[]);
insert into vectors values
    ('small', '\x00000026d1d339640100000000000000000000003a30000001000000000002001000000000000500ff0fca45c5e6'::bytea, array[0, 5, 4095]::bigint[]),
    ('bitset', '\x00000025d1d339640100000000000000000000003b3001000100008713010000000100000087137011f42dc0a0'::bytea, array(select g from generate_series(0, 4999) g) || 70000::bigint),
    ('high', '\x00000038d1d339640200000000000000000000003a3000000100000000000000100000000300010000003a300000010000000000000010000000070050e5386b'::bytea, array[3, 4294967303]::bigint[]),
    ('runs', '\x0000001fd1d339640100000000000000000000003b300000010000cf0701006400cf0798eb1f76'::bytea, array(select g from generate_series(100, 2099) g)),
    ('empty', '\x0000000cd1d339640000000000000000bf18480c'::bytea, '{}'::bigint[]),
    ('dense', '\'::bytea, array(select g from generate_series(0, 19998, 2) g) || 21474836481::bigint);
create function cm(tables jsonb, extra jsonb default '{}', r int default 1) returns bigint language sql as $$
  select commit(jsonb_build_object('ref', r, 'author', 'ana', 'actor', 'test', 'operation', 'append', 'tables', tables) || extra);
$$;
-- A stored data file of `n` rows.
create function fj(id bigint, n bigint default 10) returns jsonb language sql as $$
  select jsonb_build_object('file_id', id, 'path', 'gs://lake/t/' || id || '.parquet', 'record_count', n,
    'file_size', 1000, 'footer_size', 100);
$$;
-- An inline data file of `n` rows, whose content is `bytes` bytes.
create function ij(id bigint, n bigint default 10, bytes int default 100) returns jsonb language sql as $$
  select jsonb_build_object('file_id', id, 'inline', repeat('ab', bytes), 'record_count', n, 'file_size', bytes,
    'footer_size', 10);
$$;
-- An inline vector of `positions` for file `id`, replacing the vector that began at `base`.
create function dvj(id bigint, positions bigint[], base bigint default null) returns jsonb language sql as $$
  select jsonb_build_object('file_id', id, 'base_seq', base, 'cardinality', (select count(distinct p) from unnest(positions) p),
    'inline', encode(dv_encode(positions), 'hex'));
$$;
create function mk(name text) returns uuid language plpgsql as $$
declare t uuid := gen_random_uuid();
begin
  perform cm(jsonb_build_array(jsonb_build_object('table_id', t,
    'create', jsonb_build_object('namespace', '["db"]'::jsonb, 'name', name, 'location', 'gs://lake/' || name),
    'fields', '[{"field_id": 1, "new": true, "position": 1, "name": "id", "type": "long", "required": true}]'::jsonb)));
  return t;
end $$;
create function dv_of(r int, t uuid, id bigint) returns bigint[] language sql as $$
  select array(select dv_positions(inline) order by 1) from visible_dvs(r, t, 9223372036854775806) where file_id = id;
$$;
create function rows_of(r int, t uuid) returns bigint language sql as $$
  select sum(rows) from live_rows(r, t, 9223372036854775806);
$$;

-- case: blobs from another implementation decode to their positions; ours decode back, and match byte for byte
-- rules: DV-2
select expect(array(select dv_positions(blob) order by 1) = positions, name || ': positions') from vectors;
select expect(array(select dv_positions(dv_encode(positions)) order by 1) = positions, name || ': our encoding decodes')
  from vectors;
select expect(dv_encode(positions) = blob, name || ': the same bytes') from vectors where name in ('small', 'high', 'empty', 'dense');
select expect(crc32('123456789'::bytea) = 3421780262, 'the CRC-32 check value');
select expect_error(format('select dv_positions(%L::bytea)', overlay(blob placing '\x00'::bytea from 41 for 1)), '22023',
  'a damaged position that leaves the bitmap well formed: only the checksum catches it')
  from vectors where name = 'small';
select expect_error(format('select dv_positions(%L::bytea)', overlay(blob placing '\xd1d33965'::bytea from 5 for 4)), '22023', 'a wrong magic')
  from vectors where name = 'small';
select expect_error(format('select dv_positions(%L::bytea)', blob || '\x00'::bytea), '22023', 'a wrong length')
  from vectors where name = 'small';

-- case: a vector deletes rows of its file where it is visible, and is inherited like any versioned object
-- rules: DV-1, DV-5
select mk('t') as t \gset
select cm(format('[{"table_id": "%s", "add": [%s, %s]}]', :'t', fj(1), fj(2))::jsonb) as s1 \gset
select cm(format('[{"table_id": "%s", "dvs": [%s]}]', :'t', dvj(1, '{1,3}'))::jsonb, '{"operation": "delete"}') as s2 \gset
select expect(dv_of(1, :'t', 1) = '{1,3}' and rows_of(1, :'t') = 18, 'main: two rows of file 1 deleted');
select branch(2, 'b', :s2 + 1, 1, :s2);
select setval('commit_seq_gen', :s2 + 1);
select expect(dv_of(2, :'t', 1) = '{1,3}', 'b inherits the vector');
select cm(format('[{"table_id": "%s", "dvs": [%s]}]', :'t', dvj(1, '{1,3,5}', :s2))::jsonb, '{"operation": "delete"}', 2) as b1 \gset
select expect(dv_of(2, :'t', 1) = '{1,3,5}' and rows_of(2, :'t') = 17, 'b''s own vector replaces it in b');
select expect(dv_of(1, :'t', 1) = '{1,3}' and rows_of(1, :'t') = 18, 'main keeps its own');
select cm(format('[{"table_id": "%s", "remove": [1]}]', :'t')::jsonb, '{"operation": "delete"}');
select expect((select count(*) from visible_dvs(1, :'t', 9223372036854775806)) = 0 and rows_of(1, :'t') = 10,
  'a vector applies only while its file is visible');

-- case: a snapshot counts the vectors its commit sets
-- rules: CMT-1
select mk('t') as t \gset
select cm(format('[{"table_id": "%s", "add": [%s, %s]}]', :'t', fj(1), fj(2))::jsonb) as added \gset
select cm(jsonb_build_array(jsonb_build_object('table_id', :'t', 'dvs', jsonb_build_array(dvj(1, '{0}'), dvj(2, '{1}')))),
          '{"operation": "delete"}') as deleted \gset
select expect((select summary ->> 'changed-vectors' = '0' from snapshot where snapshot_id = :added), 'a commit of files');
select expect((select summary ->> 'changed-vectors' = '2' from snapshot where snapshot_id = :deleted), 'a commit of vectors');

-- case: a Puffin file is under its intent as a file is: an expired one is refused, a valid one goes with the commit
-- rules: RET-7 CMT-10
select mk('tp') as t \gset
select cm(format('[{"table_id": "%s", "add": [%s]}]', :'t', fj(1))::jsonb);
select register_intent('gs://lake/tp/late.puffin', :'t', 1, '-1 second'), register_intent('gs://lake/tp/dv.puffin', :'t', 1, '1 hour');
select expect_error(format('select cm(%L::jsonb, ''{"operation": "delete"}'')', format('[{"table_id": "%s", "dvs": [{"file_id": 1,
  "base_seq": null, "path": "gs://lake/tp/late.puffin", "content_offset": 4, "content_size": 46, "cardinality": 3}]}]', :'t')),
  '22023', 'a vector in a Puffin file whose intent expired');
select cm(format('[{"table_id": "%s", "dvs": [{"file_id": 1, "base_seq": null, "path": "gs://lake/tp/dv.puffin",
  "content_offset": 4, "content_size": 46, "cardinality": 3}]}]', :'t')::jsonb, '{"operation": "delete"}');
select expect(not exists (select 1 from intent where path = 'gs://lake/tp/dv.puffin'), 'its intent went with the commit');

-- case: a vector is stored in a Puffin file or inline, never both
-- rules: DV-3
select mk('t') as t \gset
select cm(format('[{"table_id": "%s", "add": [%s]}]', :'t', fj(1))::jsonb);
select cm(format('[{"table_id": "%s", "dvs": [{"file_id": 1, "base_seq": null, "path": "gs://lake/t/dv.puffin",
  "content_offset": 4, "content_size": 46, "cardinality": 3}]}]', :'t')::jsonb, '{"operation": "delete"}');
select expect((select path = 'gs://lake/t/dv.puffin' and content_offset = 4 and inline is null and cardinality = 3
                 from visible_dvs(1, :'t', 9223372036854775806)), 'in a Puffin file');
select expect_error(format('insert into deletion_vector values (%L, 1, ''p'', 4, 10, 1, ''\x00'', 1, 99)', :'t'), '23514', 'both');
select expect_error(format('insert into deletion_vector values (%L, 1, null, null, 5, 1, ''\x00'', 1, 99)', :'t'), '23514',
  'an inline vector whose size is not its length');
select expect_error(format('insert into deletion_vector values (%L, 1, ''p'', null, 5, 1, null, 1, 99)', :'t'), '23514',
  'a Puffin vector without its offset');

-- case: a vector replaces the one it started from with a superset, or the commit fails
-- rules: DV-4
select mk('t') as t \gset
select cm(format('[{"table_id": "%s", "add": [%s, %s]}]', :'t', fj(1), fj(2))::jsonb);
select cm(format('[{"table_id": "%s", "dvs": [%s]}]', :'t', dvj(1, '{1,3}'))::jsonb, '{"operation": "delete"}') as d1 \gset
select expect_error(format($$select cm('[{"table_id": "%s", "dvs": [%s]}]')$$, :'t', dvj(1, '{1,3,4}')), '40001',
  'a writer that did not see the vector');
select expect_error(format($$select cm('[{"table_id": "%s", "dvs": [%s]}]')$$, :'t', dvj(1, '{1,3,4}', :d1 - 1)), '40001',
  'a writer that started from another vector');
select expect_error(format($$select cm('[{"table_id": "%s", "dvs": [%s]}]')$$, :'t', dvj(1, '{1,4}', :d1)), '22023',
  'a vector that drops a deleted position');
select expect_error(format($$select cm('[{"table_id": "%s", "dvs": [%s]}]')$$, :'t', dvj(1, '{1,3,10}', :d1)), '22023',
  'a position beyond the file''s 10 rows');
select expect_error(format($$select cm('[{"table_id": "%s", "dvs": [%s]}]')$$, :'t',
  jsonb_set(dvj(1, '{1,3,4}', :d1), '{cardinality}', '4')), '22023', 'a cardinality that is not the count of positions');
select expect_error(format($$select cm('[{"table_id": "%s", "dvs": [%s]}]')$$, :'t', dvj(9, '{1}')), '40001', 'a file that is not visible');
select expect(cm(format('[{"table_id": "%s", "dvs": [%s]}]', :'t', dvj(1, '{1,3,4}', :d1))::jsonb) > :d1, 'a superset');
select cm(format('[{"table_id": "%s", "dvs": [{"file_id": 2, "base_seq": null, "path": "p", "content_offset": 4,
  "content_size": 40, "cardinality": 5}]}]', :'t')::jsonb) as d2 \gset
select expect_error(format($$select cm('[{"table_id": "%s", "dvs": [{"file_id": 2, "base_seq": %s, "path": "q",
  "content_offset": 4, "content_size": 40, "cardinality": 4}]}]')$$, :'t', :d2), '22023', 'a Puffin vector with fewer positions');

-- case: an inline file has no path, its bytes in inline_file, its exact size, under the table's limit
-- rules: INL-1
select mk('t') as t \gset
select cm(format('[{"table_id": "%s", "add": [%s]}]', :'t', ij(1))::jsonb);
select expect((select path is null from data_file where file_id = 1)
  and (select length(content) = 100 from inline_file where file_id = 1), 'no path, 100 bytes inline');
select expect_error(format($$select cm('[{"table_id": "%s", "add": [{"file_id": 2, "record_count": 1, "file_size": 1, "footer_size": 1}]}]')$$, :'t'),
  '22023', 'no path and no content');
select expect_error(format($$select cm('[{"table_id": "%s", "add": [%s]}]')$$, :'t', ij(3) || '{"path": "p"}'), '22023', 'both');
select expect_error(format($$select cm('[{"table_id": "%s", "add": [%s]}]')$$, :'t', jsonb_set(ij(4), '{file_size}', '99')), '22023',
  'a file_size that is not the length');
select expect_error(format($$select cm('[{"table_id": "%s", "add": [%s]}]')$$, :'t', ij(5, 1, 65537)), '22023', 'above the default limit');
select cm(format('[{"table_id": "%s", "properties": {"inline.max-bytes": "50"}}]', :'t')::jsonb);
select expect_error(format($$select cm('[{"table_id": "%s", "add": [%s]}]')$$, :'t', ij(6)), '22023', 'above the table''s limit');

-- case: a replace keeps the live rows and only moves files; flushing inline files is one
-- rules: CMT-11, INL-2
select mk('t') as t \gset
select cm(format('[{"table_id": "%s", "add": [%s, %s, %s]}]', :'t', ij(1, 2), ij(2, 3), ij(3, 5))::jsonb);
select cm(format('[{"table_id": "%s", "dvs": [%s]}]', :'t', dvj(3, '{0}'))::jsonb, '{"operation": "delete"}');
select expect(not inline_flush_due(1, :'t'), 'not due under the defaults');
select cm(format('[{"table_id": "%s", "properties": {"inline.flush-bytes": "250"}}]', :'t')::jsonb);
select expect(inline_flush_due(1, :'t'), 'due: 300 bytes inline, above 250');
select cm(format('[{"table_id": "%s", "properties": {"inline.flush-bytes": null, "inline.flush-age-seconds": "0"}}]', :'t')::jsonb);
select pg_sleep(0.01);
select expect(inline_flush_due(1, :'t'), 'due: older than 0 seconds');
select expect_error(format($$select cm('[{"table_id": "%s", "remove": [1, 2, 3], "add": [%s]}]', '{"operation": "replace"}')$$, :'t', fj(10, 10)),
  '22023', 'a replace that adds a deleted row back');
select expect_error(format($$select cm('[{"table_id": "%s", "remove": [1, 2, 3], "add": [%s], "properties": {"k": "v"}}]', '{"operation": "replace"}')$$,
  :'t', fj(10, 9)), '22023', 'a replace that changes more than files');
select cm(format('[{"table_id": "%s", "remove": [1, 2, 3], "add": [%s]}]', :'t', fj(10, 9))::jsonb, '{"operation": "replace"}');
select expect((select array_agg(file_id) from visible_files(1, :'t', 9223372036854775806)) = '{10}' and rows_of(1, :'t') = 9
  and not inline_flush_due(1, :'t'), 'flushed: one stored file with the 9 live rows');

-- case: a stored footer is the file's footer, footer_size bytes long
-- rules: FTR-1
select mk('t') as t \gset
select cm(format('[{"table_id": "%s", "add": [%s]}]', :'t', fj(1) || jsonb_build_object('footer', repeat('cd', 100)))::jsonb);
select expect((select length(footer) = 100 from file_footer where file_id = 1), 'stored');
select expect_error(format($$select cm('[{"table_id": "%s", "add": [%s]}]')$$, :'t', fj(2) || jsonb_build_object('footer', repeat('cd', 99))),
  '22023', 'a footer that is not footer_size bytes long');
